-- Disposable-local fixtures ONLY. No production/provider assumptions.
create schema report_test;
create table report_test.checks(name text primary key);
create function report_test.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'FAIL: %',label;end if;insert into report_test.checks values(label);raise notice 'PASS: %',label;end $$;
create function report_test.denied(statement text,label text) returns void language plpgsql as $$ declare rejected boolean=false;begin begin execute statement;exception when others then rejected=true;end;perform report_test.ok(rejected,label);end $$;
create function report_test.place(qty integer default 1,mixed boolean default false) returns uuid language plpgsql as $$ declare oid uuid=gen_random_uuid();lines jsonb;begin
 lines=jsonb_build_array(jsonb_build_object('id','15151515-0000-4000-8000-000000000002','quantity',qty,'expectedPriceMinor',100000));
 if mixed then lines=lines||jsonb_build_array(jsonb_build_object('id','17171717-0000-4000-8000-000000000101','kind','deal','quantity',2,'expectedPriceMinor',100001,'expectedDealRevision',(select revision from app_private.deal_settings where deal_id='17171717-0000-4000-8000-000000000101')));end if;
 perform public.place_guest_order(oid,repeat('a',64),repeat('b',64),lines,'{"name":"Synthetic reporting guest","phone":"+923001234567","address":"Synthetic test address","city":"Test City"}','{"id":"test","label":"Synthetic delivery","feeMinor":12345}','{"id":"bank-transfer","label":"Synthetic bank","allocation":"temporary","accountScope":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","accountTitle":"Synthetic only","destination":"TEST ONLY"}','{"mode":"development","version":"reporting-test","paymentSeconds":604800,"reviewExtensionSeconds":30}');return oid;
end $$;
create function report_test.pay(oid uuid,extra integer default 0) returns void language plpgsql as $$ begin perform public.review_manual_payment(oid,(select revision from app_private.commerce_orders where order_id=oid),'verify',gen_random_uuid(),jsonb_build_object('checkedHistory',true,'amountMinor',(select total_minor+extra from public.orders where id=oid),'reference','SYNTHETIC-'||oid,'reacquire',false));end $$;
create function report_test.step(oid uuid,action text) returns void language plpgsql as $$ begin perform public.admin_order_action(oid,(select revision from app_private.commerce_orders where order_id=oid),action,gen_random_uuid());end $$;
create function report_test.finance(oid uuid,action text,data jsonb,key uuid default gen_random_uuid()) returns jsonb language plpgsql as $$ begin return public.admin_finance_action(oid,coalesce((select revision from app_private.finance_versions where order_id=oid),0),key,action,data);end $$;
create function report_test.selection(oid uuid,deal boolean,qty integer,shipping bigint default 0,overpay bigint default 0) returns jsonb language sql as $$ select jsonb_build_object('items',case when qty=0 then '[]'::jsonb else jsonb_build_array(jsonb_build_object('itemId',(select id from public.order_items where order_id=oid and (deal_id is not null)=deal),'variantId','15151515-0000-4000-8000-000000000002','quantity',qty)) end,'shippingMinor',shipping,'overpaymentMinor',overpay);$$;
create function report_test.request(oid uuid,selection jsonb) returns uuid language plpgsql as $$ declare key uuid=gen_random_uuid();begin perform report_test.finance(oid,'request',jsonb_build_object('reason','Synthetic refund request','selection',selection),key);return key;end $$;
create function report_test.send(oid uuid,rid uuid,ref text default null) returns jsonb language sql as $$ select report_test.finance(oid,'send',jsonb_build_object('refundId',rid,'reason','Synthetic outgoing-history verification','method','bank-transfer','account','Synthetic sending account','reference',coalesce(ref,'SYNTHETIC-REFUND-'||rid),'sentAt',clock_timestamp(),'checkedHistory',true));$$;
set request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
